def W(t,rows,top): return {"type":"words","title":t,"hint":H,"rows":rows,"top":top}
def TF(rows,top): return {"type":"tf","title":"صَحٌّ أَمْ خَطَأٌ؟","rows":rows,"top":top}
DG='٠١٢٣٤٥٦٧٨٩'; ar=lambda x:''.join(DG[int(c)] if c.isdigit() else c for c in str(x))
def mk(rows):
  out=[]
  for q,c,ds,p in rows:
    o=list(ds); o.insert(p,c); assert len(set(o))==len(o),o; out.append([q,o])
  return out
